/// <summary>
/// MPJ_3338_AMEXCustomerPaymentProcessing - vpotula
/// Extension of <c>ledgerJournalCheckPost</c> class
/// </summary>
[ExtensionOf(classStr(ledgerJournalCheckPost))]
public final class METLedgerJournalCheckPost_Extension
{
    public Map mapTxtErrorLog = new Map(Types::String, Types::String);
    public Boolean isErrorPrinted = false;
}

Method.Source:
/// <summary>
/// Extended stand method to update AMEX journal number.
/// </summary>
/// <returns>LedgerJournalId</returns>
public LedgerJournalId transferToNewLedgerTable()
{
    JournalId metNewJournal = next transferToNewLedgerTable();
    
    //MPJ_3338_AMEXCustomerPaymentProcessing - vpotula
    LedgerJournalTable  metNewJournalTable = LedgerJournalTable::find(metNewJournal, false);
    if (metNewJournalTable
            && metNewJournalTable.JournalName == CustParameters::find().METAMEXJournalName)
    {
        if(!CustParameters::find().METAMEXIsAdhocJournal)
        {
            CustParameters::METUpdateAMEXJournalNum(metNewJournal);
            if (metNewJournalTable.OriginalJournalNum)
            {
                CustParameters::METUpdateAMEXFreeTextInvJournalNum(metNewJournalTable.OriginalJournalNum);
            }
        }
        else
        {
            // MPJ-19186 - Update FTI flag for Adhoc journals
            LedgerJournalTable  metOrigJournalTable = LedgerJournalTable::find(metNewJournalTable.OriginalJournalNum, true);
            if (metOrigJournalTable)
            {
                ttsbegin;
                metOrigJournalTable.METAMEXProcessFTI = NoYes::Yes;
                metOrigJournalTable.doUpdate();
                ttscommit;
            }
        }
    }
    return metNewJournal;
}

    /// <summary>
    /// coc created for updating the text with details
    /// CB718 DMF - VM
    /// </summary>
    /// <param name = "_ledgerJournalTrans">_ledgerJournalTrans</param>
    public void updateTransInfoLog(LedgerJournalTrans _ledgerJournalTrans)
    {
        #Define.UserTab('\t')

        Integer         xloc = transLogPoint;
        Integer         yloc = infolog.num(0);
        str             currentLine1;
        Voucher         voucherloc;
        
        next updateTransInfoLog(_ledgerJournalTrans);

        while (xloc < yloc)
        {
            xloc++;

            currentLine1 = strRem(infolog.text(xloc), #UserTab);

            if (postingResults != null)
            {
                if (_ledgerJournalTrans.Voucher == '')
                {
                    voucherloc = LedgerJournalCheckPostResults::getVoucherFromLogText(currentLine1);
                    if (voucherloc == '')
                    {
                        // continue because calling the LedgerJournalCheckPostResults.updateErrorLog
                        // method with a blank voucher has terrible performance and will not change the results
                        continue;
                    }
                }
                else
                {
                    voucherloc = _ledgerJournalTrans.Voucher;
                    
                    if (mapTxtErrorLog.exists(voucherloc))
                    {
                        str valueError = mapTxtErrorLog.lookup(voucherloc);
                        mapTxtErrorLog.insert(voucherloc, strFmt("@MET:StrfmtLinenumMod",valueError,currentLine1,_ledgerJournalTrans.LineNum) + '\r\n');
                    }
                    else
                    {
                        mapTxtErrorLog.insert(voucherloc, strFmt("@MET:StrfmtLinenum12",currentLine1,_ledgerJournalTrans.LineNum)+ '\r\n');
                    }
                }
            }
        }
        transLogPoint = yloc;
    }

    /// <summary>
    /// COC with details of error being pushed to telemetry
    /// CB718 DMF - VM
    /// </summary>
    /// <param name = "_ledgerJournalTable">_ledgerJournalTable</param>
    /// <param name = "set">set</param>
    public void updateSystemBlock(LedgerJournalTable _ledgerJournalTable, boolean set)
    {
        next updateSystemBlock(_ledgerJournalTable, set);

        if (!mapTxtErrorLog.empty() && !isErrorPrinted)
        {
            MapEnumerator mapEnumerator;
            Notes Errmsg;
            TableId tableId = TableNum(LedgerJournalTable);
            DictFieldGroup dictFieldGrp = new DictFieldGroup(tableId,METConstants::METReference);
            int counter,fieldId;
            DictField dictField;
            METTelemetryLedgerJournalCheckPostLogging metLedgerJournalCheckPostLogging = METTelemetryLedgerJournalCheckPostLogging::construct(Errmsg);

            mapEnumerator = mapTxtErrorLog.getEnumerator();
            while (mapEnumerator.moveNext())
            {
                isErrorPrinted = true;
                Errmsg += strfmt("@MET:Multiplestrmt",mapEnumerator.currentKey(),mapEnumerator.currentValue()) + '\r\n';//copy all Error records
            }

            // If table is having table group METReference then check all the fields and assign those fields as custom dimensions
            if (dictFieldGrp)
            {
                for (counter = 1; counter <= dictFieldGrp.numberOfFields(); counter++)
                {
                    fieldId = dictFieldGrp.field(counter);

                    dictField = new DictField(tableId, fieldId);
                    if (_ledgerJournalTable.(fieldId))
                    {
                        Errmsg += strFmt("@MET:Multiplestrmt",dictField.label(),any2str(_ledgerJournalTable.(fieldId)));
                        //Reference Added as custom dimension
                        metLedgerJournalCheckPostLogging.addRuntimeProperty(dictField.label(),any2str(_ledgerJournalTable.(fieldId)));
                    }
                }
            }

            metLedgerJournalCheckPostLogging.errmsg = Errmsg;
            metLedgerJournalCheckPostLogging.processEvent(METApplicationInsightsEventNames::JournalCheckPostLog);
        }
    }

    /// <summary>
    /// MET_122589_RPAGeneralLedgerIntegration developed by yadavpa on 25/03/2024
    /// RPA Ledger Integration
    /// </summary>
    /// <param name = "_journalTable"></param>
    protected void updateTableInfoLog(LedgerJournalTable _journalTable)
    {
        LedgerJournalTable  ledgerJournalTableErrorCapture;
        boolean             flag = true;

        next  updateTableInfoLog(_journalTable);
        if(flag)
        {
            select forupdate ledgerJournalTableErrorCapture where
                ledgerJournalTableErrorCapture.RecId == _journalTable.RecId ;
            if(ledgerJournalTableErrorCapture.RecId)
            {
                ttsbegin;
                ledgerJournalTableErrorCapture.METErrorLog = tableErrorLog;
                ledgerJournalTableErrorCapture.update();
                ttscommit;

                flag = false;
            }
        }
    }
